glsl:
vec4 effect(vec2 uv) {
  vec2 p = uv - 0.5; p.x *= uRatio;
  float a = atan(p.y, p.x) + uTime * 0.25;
  float r = length(p);
  float seg = 6.28318 / 6.0;
  a = mod(a, seg); a = abs(a - seg * 0.5);
  p = vec2(cos(a), sin(a)) * r; p.x /= uRatio;
  return mix(getColor(uv), getColor(p + 0.5), uAmount);
}
